1	import React, { useState } from "react";
2	import { useNavigate } from "react-router-dom";
3	import { ScanLine } from "lucide-react";
4	import { Input } from "@/components/ui/input";
5	import { Button } from "@/components/ui/button";
6	import {
7	  Select,
8	  SelectContent,
9	  SelectItem,
10	  SelectTrigger,
11	  SelectValue,
12	} from "@/components/ui/select";
13	import { PAGE_TYPES } from "@/lib/constants";
14	import { cn } from "@/lib/utils";
15	import type { PageType } from "@/types";
16	
17	interface UrlInputProps {
18	  showPageType?: boolean;
19	  buttonText?: string;
20	  size?: "default" | "lg";
21	  className?: string;
22	  onSubmit?: (url: string, pageType: PageType) => void;
23	}
24	
25	export const UrlInput = React.forwardRef<HTMLFormElement, UrlInputProps>(function UrlInput({
26	  showPageType = false,
27	  buttonText = "Analyze Now",
28	  size = "default",
29	  className,
30	  onSubmit,
31	}, ref) {
32	  const [url, setUrl] = useState("");
33	  const [pageType, setPageType] = useState<PageType>("landing");
34	  const navigate = useNavigate();
35	
36	  const handleSubmit = (e: React.FormEvent) => {
37	    e.preventDefault();
38	    const trimmed = url.trim();
39	    if (!trimmed) return;
40	
41	    // Normalize: add https:// if missing
42	    const normalized = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
43	
44	    if (onSubmit) {
45	      onSubmit(normalized, pageType);
46	    } else {
47	      navigate(`/scan?url=${encodeURIComponent(normalized)}&type=${pageType}`);
48	    }
49	  };
50	
51	  const isLarge = size === "lg";
52	
53	  return (
54	    <form ref={ref} onSubmit={handleSubmit} className={cn("w-full", className)}>
55	      <div className={cn("flex gap-2", isLarge ? "flex-col sm:flex-row" : "flex-row")}>
56	        <div className="relative flex-1">
57	          <Input
58	            type="url"
59	            placeholder="https://your-website.com/landing-page"
60	            value={url}
61	            onChange={(e) => setUrl(e.target.value)}
62	            className={cn(
63	              "border-border/50 bg-card pr-4 pl-4 text-foreground placeholder:text-muted-foreground focus-visible:ring-primary/20 focus-visible:border-primary",
64	              isLarge ? "h-14 text-base rounded-xl" : "h-10 text-sm rounded-lg"
65	            )}
66	          />
67	        </div>
68	        {showPageType && (
69	          <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
70	            <SelectTrigger
71	              className={cn(
72	                "w-40 border-border/50 bg-card",
73	                isLarge ? "h-14 rounded-xl" : "h-10 rounded-lg"
74	              )}
75	            >
76	              <SelectValue placeholder="Page type" />
77	            </SelectTrigger>
78	            <SelectContent>
79	              {PAGE_TYPES.map((type) => (
80	                <SelectItem key={type.value} value={type.value}>
81	                  {type.label}
82	                </SelectItem>
83	              ))}
84	            </SelectContent>
85	          </Select>
86	        )}
87	        <Button
88	          type="submit"
89	          className={cn(
90	            "shrink-0 font-semibold",
91	            isLarge
92	              ? "h-14 px-8 text-base rounded-xl"
93	              : "h-10 px-5 text-sm rounded-lg"
94	          )}
95	        >
96	          <ScanLine className={cn("mr-2", isLarge ? "h-5 w-5" : "h-4 w-4")} />
97	          {buttonText}
98	        </Button>
99	      </div>
100	    </form>
101	  );
102	});
103

1	import React, { useEffect, useState } from "react";
2	import { getScoreHex, getScoreLabel } from "@/lib/score-utils";
3	import { cn } from "@/lib/utils";
4	
5	interface ScoreRingProps {
6	  score: number;
7	  size?: number;
8	  strokeWidth?: number;
9	  showLabel?: boolean;
10	  className?: string;
11	}
12	
13	export const ScoreRing = React.forwardRef<HTMLDivElement, ScoreRingProps>(function ScoreRing({
14	  score,
15	  size = 120,
16	  strokeWidth = 8,
17	  showLabel = true,
18	  className,
19	}, ref) {
20	  const [animatedOffset, setAnimatedOffset] = useState(0);
21	  const radius = (size - strokeWidth) / 2;
22	  const circumference = 2 * Math.PI * radius;
23	  const targetOffset = circumference * (1 - score / 100);
24	
25	  useEffect(() => {
26	    setAnimatedOffset(circumference);
27	    const timer = setTimeout(() => setAnimatedOffset(targetOffset), 50);
28	    return () => clearTimeout(timer);
29	  }, [score, circumference, targetOffset]);
30	
31	  const color = getScoreHex(score);
32	  const label = getScoreLabel(score);
33	  const center = size / 2;
34	  const fontSize = size * 0.28;
35	  const labelSize = size * 0.09;
36	
37	  // Glow shadow based on score color
38	  const glowShadow = score >= 70
39	    ? "drop-shadow(0 0 6px rgba(34, 197, 94, 0.2))"
40	    : score >= 40
41	    ? "drop-shadow(0 0 6px rgba(245, 158, 11, 0.2))"
42	    : "drop-shadow(0 0 6px rgba(239, 68, 68, 0.2))";
43	
44	  return (
45	    <div
46	      ref={ref}
47	      role="img"
48	      aria-label={`CRO Score: ${score} out of 100`}
49	      className={cn("relative inline-flex flex-col items-center", className)}
50	    >
51	      {/* Subtle radial gradient backdrop */}
52	      <div
53	        className="absolute rounded-full"
54	        style={{
55	          width: size,
56	          height: size,
57	          background: `radial-gradient(circle, ${color}08 0%, transparent 70%)`,
58	        }}
59	      />
60	      <svg
61	        width={size}
62	        height={size}
63	        className="transform -rotate-90"
64	        style={{ filter: glowShadow }}
65	      >
66	        {/* Background circle */}
67	        <circle
68	          cx={center}
69	          cy={center}
70	          r={radius}
71	          fill="none"
72	          stroke="currentColor"
73	          strokeWidth={strokeWidth}
74	          className="text-muted/60"
75	        />
76	        {/* Score circle */}
77	        <circle
78	          cx={center}
79	          cy={center}
80	          r={radius}
81	          fill="none"
82	          stroke={color}
83	          strokeWidth={strokeWidth}
84	          strokeLinecap="round"
85	          strokeDasharray={circumference}
86	          strokeDashoffset={animatedOffset}
87	          style={{ transition: "stroke-dashoffset 1s ease-out" }}
88	        />
89	      </svg>
90	      {/* Score number centered */}
91	      <div className="absolute inset-0 flex flex-col items-center justify-center">
92	        <span
93	          className="font-bold text-foreground tabular-nums"
94	          style={{ fontSize: `${fontSize}px`, lineHeight: 1 }}
95	        >
96	          {score}
97	        </span>
98	        <span
99	          className="text-muted-foreground"
100	          style={{ fontSize: `${labelSize}px` }}
101	        >
102	          /100
103	        </span>
104	      </div>
105	      {showLabel && (
106	        <span
107	          className="mt-1 text-xs font-medium"
108	          style={{ color }}
109	        >
110	          {label}
111	        </span>
112	      )}
113	    </div>
114	  );
115	});
